for (const [n, c] of Object.entries(COST)) ok(C(n).cost === c, `cost: ${n} $${c}`, C(n).cost);

// ---------------------------------------------------------------- compat flags
ok(C('mega_pidgeot').blueprint_compat === true && C('pokedex').blueprint_compat === false && C('professor').blueprint_compat === false && C('treasure_eatery').blueprint_compat === false, 'blueprint_compat: Mega Pidgeot on; Pokédex / Professor / Treasure Eatery off');
ok(C('mega_kangaskhan').blueprint_compat === false && C('spearow').blueprint_compat === false && C('onix').blueprint_compat === false, 'blueprint_compat of reworked jokers stays 3.2.1 (Mega Kangaskhan, Spearow, Onix)');
ok(C('wartortle').perishable_compat === false && C('zubat').perishable_compat === false && C('mareep').perishable_compat === false && C('treecko').perishable_compat === true, 'perishable_compat: Wartortle / Zubat / Mareep off, Treecko on');
ok(C('mega_gengar').eternal_compat === true, 'eternal_compat: Mega Gengar on');
ok(['xmult', 'volatile', 'round_evo', 'lightning_type', 'stage_basic', 'pokemon'].every((x) => C('voltorb').attributes.includes(x)) && C('bulbasaur').attributes.includes('starter'), 'the 3.9.1 attributes (+ the type / stage / pokemon ones of load_pokemon)', C('voltorb').attributes);

// ---------------------------------------------------------------- enhancement gates
const GATES = { vaporeon: 'm_bonus', jolteon: 'm_gold', flareon: 'm_mult', leafeon: 'm_lucky', glaceon: 'm_glass', probopass: 'm_stone', gholdengo: 'm_gold' };
for (const [n, g] of Object.entries(GATES)) ok(C(n).enhancement_gate === g, `enhancement gate: ${n} needs ${g}`, C(n).enhancement_gate);
{
  start('PK391GATE');
  const pp = C('probopass');
  for (const c of G.playing_cards) if (c.config.center.key === 'm_stone') c.set_ability(P_CENTERS.c_base);
  ok(pp.in_pool(pp) === false, 'gate: no Stone card in the deck -> Probopass never spawns');
  G.playing_cards[0].set_ability(P_CENTERS.m_stone);
  ok(pp.in_pool(pp) === true, 'gate: a Stone card in the deck -> it can');
}

// ---------------------------------------------------------------- config numbers (read by the ported logic in play)
ok(C('voltorb').config.extra.Xmult === 1.75 && C('electrode').config.extra.Xmult === 2.25, 'config: Voltorb X1.75, Electrode X2.25');
{
  start('PK391VOLT');
  const v = add('j_poke_voltorb');
  const r = play(hand(['S_A']));
  ok(r.total.mult === 1.75 && v.debuff, 'Voltorb fires X1.75 (3.9.1) then faints', r.total);
}
{
  start('PK391ELEC');
  add('j_poke_electrode');
  const d0 = G.GAME.dollars;
  const r = play(hand(['S_A']));
  ok(r.total.mult === 2.25 && G.GAME.dollars === d0 + 3, 'Electrode fires X2.25 (3.9.1) and $3', { t: r.total, d: G.GAME.dollars - d0 });
}
ok(C('larvitar').config.extra.chip_mod === 10 && C('pupitar').config.extra.chip_mod === 15, 'config: Larvitar +10 / Pupitar +15 Chips per Full House card');
{
  start('PK391LARV');
  add('j_poke_larvitar');
  const cards = hand(['S_K', 'H_K', 'D_K', 'S_2', 'H_2']);
  play(cards);
  ok(cards.every((c) => c.ability.perma_bonus === 10), 'Larvitar: every Full House card permanently +10 Chips', cards.map((c) => c.ability.perma_bonus));
}
ok(C('grubbin').config.extra.rounds === 4 && C('charjabug').config.extra.mult === 7, 'config: Grubbin 4 rounds, Charjabug +7');
{
  start('PK391CHAR');
  add('j_poke_charjabug');
  const r = play(hand(['S_A']));
  ok(r.total.mult === 1 + 7, 'Charjabug: +7 Mult for itself (the one Lightning joker)', r.total);
}
ok(C('kricketot').config.extra.money === 4 && C('kricketune').config.extra.money === 5, 'config: Kricketot $4 (taken); Kricketune $5 (its calculate changed: kept)');
{
  start('PK391KRIC');
  add('j_poke_kricketot');
  const d0 = G.GAME.dollars;
  play(hand(['S_2', 'H_3', 'D_4', 'C_5']));
  G.E_MANAGER.flush();
  ok(G.GAME.dollars === d0 + 4, 'Kricketot: $4 for a 4-suit 4-card hand', G.GAME.dollars - d0);
}
ok(C('primeape').config.evo_rqmt === 29 && C('ursaring').config.extra.mult_mod === 2, 'config: Primeape evolves after 29 primes, Ursaring +2 per skipped pack');
// skipped (reworks): the 3.2.1 numbers stay
ok(C('spearow').config.extra.card_threshold === 20 && C('flareon').config.extra.Xmult_multi === 3 && C('qwilfish').config.extra.chip_mod === 25
  && C('jirachi_power').config.extra.every === 3 && C('golbat').config.evo_rqmt === 20 && C('ursaluna').config.extra.mult_mod === 3,
'skipped config numbers (reworks / Hazard layer / Jirachi) keep their 3.2.1 values');
ok(C('mankey').config.extra.chips === 5 && C('mankey').config.extra.chip_mod === undefined, 'renamed config keys are not taken (the ported logic reads the 3.2.1 keys)');

// ---------------------------------------------------------------- house rules / kept fixes
ok(/contains/.test(DATA.loc.descriptions.Joker.j_poke_deino.text[1]) && /contains/.test(DATA.loc.descriptions.Joker.j_poke_zweilous.text[1]), 'house rule: Deino / Zweilous "contains a Three of a Kind"');
ok(P_CENTERS.b_poke_revenantdeck && !P_CENTERS.b_poke_revenanteck, 'kept fix: the Revenant deck typo');

// ---------------------------------------------------------------- the renamed boss
{
  const hb = P_BLINDS.bl_poke_iridescent_hacker;
  ok(hb && !P_BLINDS.bl_poke_cgoose, 'the boss is registered as bl_poke_iridescent_hacker (bl_poke_cgoose is not)');
  ok(hb && hb.boss.showdown && hb.mult === 2 && hb.dollars === 8 && hb.boss_colour === '#505860' && hb.atlas === 'poke_AtlasBossblinds391' && hb.pos.y === 25, 'Iridescent Hacker: showdown, x2, $8, 3.9.1 colour + art', hb && [hb.boss_colour, hb.atlas, hb.pos]);
  ok(DATA.loc.descriptions.Blind.bl_poke_iridescent_hacker && DATA.loc.descriptions.Blind.bl_poke_iridescent_hacker.name === 'Iridescent Hacker', 'its 3.9.1 name');
  ok(AL.isRenamed('bl_poke_cgoose') && AL.resolveKey('bl_poke_cgoose', (k) => !!P_BLINDS[k]) === 'bl_poke_iridescent_hacker', 'the old key resolves to the new one (aliases.js, now active)');
  ok(AL.aliasesOf('bl_poke_iridescent_hacker').includes('bl_poke_cgoose'), '... and its stored stickers / records count for the new key');
  start('PK391HACK', {}, { noBlind: true });
  G.FORCE_BOSS = undefined;
  G.GAME.round_resets.ante = 8;
  for (const k of Object.keys(G.GAME.bosses_used)) G.GAME.bosses_used[k] = k === 'bl_poke_iridescent_hacker' ? 0 : 99;
  ok(get_new_boss() === 'bl_poke_iridescent_hacker', 'eligible at ante 8');
  G.GAME.round_resets.ante = 1;
  G.FORCE_BOSS = 'bl_poke_iridescent_hacker';
  G.GAME.round_resets.blind_choices.Boss = 'bl_poke_iridescent_hacker';
  const ch = add('j_poke_charmander'), sq = add('j_poke_squirtle');
  act({ type: 'select_blind' }); clearHand(); nextRound(); clearHand(); nextRound();
  ok(G.GAME.blind.config.blind.key === 'bl_poke_iridescent_hacker' && Array.isArray(G.GAME.blind.poke_ptypes), 'the fight: types picked at set_blind (the ported behaviour)');
  const want = (c) => G.GAME.blind.poke_ptypes.includes(c.ability.extra.ptype);
  play(hand(['S_2']));
  ok([ch, sq].every((c) => !!c.debuff === want(c)), 'after a hand: jokers of its types are debuffed');
  winRound();
}

// ---------------------------------------------------------------- art: the 3.9.1 sheets
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../../');
const roots = [ROOT];
if (process.env.MICATRO_MAIN) roots.push(path.resolve(process.env.MICATRO_MAIN));
try {
  const common = execFileSync('git', ['rev-parse', '--path-format=absolute', '--git-common-dir'], { cwd: ROOT, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }).trim();
  roots.push(path.dirname(common));
} catch { /* not a git checkout */ }
const ART = roots.map((r) => path.join(r, 'micatro/mods/pokermon/assets/2x')).find((d) => fs.existsSync(path.join(d, 'Basic Series/AtlasJokersBasicGen01-391.png')));

/** Stream a PNG (8-bit RGBA / RGB / palette, non-interlaced) and cut these rects out of it: {id: [x, y, w, h]} -> {id: RGBA}. */
async function crops(file, rects) {
  const buf = fs.readFileSync(file);
  let p = 8, w, h, ctype, pal = null, trns = null;
  const idat = [];
  while (p < buf.length) {
    const len = buf.readUInt32BE(p), type = buf.toString('latin1', p + 4, p + 8), d = buf.subarray(p + 8, p + 8 + len);
    if (type === 'IHDR') { w = d.readUInt32BE(0); h = d.readUInt32BE(4); ctype = d[9]; if (d[8] !== 8 || d[12] !== 0 || ![2, 3, 6].includes(ctype)) throw new Error(file + ': unsupported PNG'); }
    else if (type === 'PLTE') pal = d; else if (type === 'tRNS') trns = d; else if (type === 'IDAT') idat.push(d); else if (type === 'IEND') break;
    p += 12 + len;
  }
  const bpp = ctype === 6 ? 4 : ctype === 2 ? 3 : 1, stride = w * bpp;
  const out = {};
  for (const [id, [x, y, cw, ch]] of Object.entries(rects)) out[id] = { x, y, cw, ch, px: new Uint8Array(cw * ch * 4), inside: x + cw <= w && y + ch <= h };
  let prev = new Uint8Array(stride), cur = new Uint8Array(stride), row = 0, fill = -1, ftype = 0;
  const pending = [];
  const onRow = () => {
    for (const r of Object.values(out)) {
      if (!r.inside || row < r.y || row >= r.y + r.ch) continue;
      const o = (row - r.y) * r.cw * 4;
      for (let i = 0; i < r.cw; i++) {
        const s = (r.x + i) * bpp;
        let R, Gc, B, A;
        if (bpp === 1) { const k = cur[s]; R = pal[k * 3]; Gc = pal[k * 3 + 1]; B = pal[k * 3 + 2]; A = trns && k < trns.length ? trns[k] : 255; }
        else { R = cur[s]; Gc = cur[s + 1]; B = cur[s + 2]; A = bpp === 4 ? cur[s + 3] : 255; }
        r.px.set([R, Gc, B, A], o + i * 4);
      }
    }
  };
  await new Promise((resolve, reject) => {
    const inf = zlib.createInflate();
    inf.on('data', (chunk) => {
      for (let i = 0; i < chunk.length && row < h; i++) {
        const v = chunk[i];
        if (fill < 0) { ftype = v; fill = 0; continue; }
        const a = fill >= bpp ? cur[fill - bpp] : 0, b = prev[fill], c = fill >= bpp ? prev[fill - bpp] : 0;
        let val;
        switch (ftype) {
          case 0: val = v; break;
          case 1: val = v + a; break;
          case 2: val = v + b; break;
          case 3: val = v + ((a + b) >> 1); break;
          default: { const pa = Math.abs(b - c), pb = Math.abs(a - c), pc = Math.abs(a + b - 2 * c); val = v + (pa <= pb && pa <= pc ? a : pb <= pc ? b : c); }
        }
        cur[fill++] = val & 255;
        if (fill === stride) { onRow(); const t = prev; prev = cur; cur = t; fill = -1; row++; }
      }
    });
    inf.on('end', resolve); inf.on('error', reject);
    for (const d of idat) inf.write(d);
    inf.end();
    void pending;
  });
  return out;
}
const meanDiff = (a, b) => { let s = 0; for (let i = 0; i < a.length; i++) s += Math.abs(a[i] - b[i]); return s / a.length; };

if (!ART) console.log('(Pokermon art not on disk: the 3.9.1 crop checks are skipped)');
else {
  // The 3.2.1 cell of each card (data.js PokemonSprites / its own pos) vs its 3.9.1 cell, both from disk.
  const SPR321 = DATA.globals.PokemonSprites;
  const oldCell = (c) => {
    if (c.set === 'Joker') {
      const n = c.key.replace(/^j_poke_/, '');
      const info = SPR321[n];
      if (info && info.base && info.base.pos) {
        const pos = Array.isArray(info.base.pos) ? info.base.pos[0] : info.base.pos;
        const gen = C(n).gen;
        const atlas = info.gen_atlas && gen ? 'AtlasJokersBasicGen' + String(gen).padStart(2, '0') : info.others_atlas ? 'AtlasJokersBasicOthers' : 'AtlasJokersBasicNatdex';
        return { atlas: 'poke_' + atlas, pos };
      }
    }
    if (c.key === 'bl_poke_iridescent_hacker') return { atlas: 'poke_AtlasBossblinds', pos: { x: 0, y: 0 } }; // (Chartreuse Chamber's cell)
    return { atlas: c.atlas.replace(/391$/, ''), pos: c.pos };
  };
  const C2 = MODS.pokermon.content;
  const cards = [...C2.centers, ...C2.blinds, ...C2.stickers, ...MODS.pokermon.sleeves].filter((c) => /391$/.test(c.atlas || '') && c.pos && !/AtlasJokersBasicOthers391|AtlasDecksBasic391/.test(c.atlas) || ['j_poke_rival', 'b_poke_pokemondeck'].includes(c.key));
  const fileOf = (a) => decodeURIComponent(ATLASES[a].src).replace(/^.*\/assets\/2x\//, '');
  const cell = (a, pos) => { const A = ATLASES[a], cw = (A.px || 71) * 2, chh = (A.py || 95) * 2; return [pos.x * cw, pos.y * chh, cw, chh]; };
  const want = {}; // file -> rects
  const req = (file, id, rect) => ((want[file] || (want[file] = {}))[id] = rect);
  for (const c of cards) {
    const o = oldCell(c);
    if (!ATLASES[o.atlas]) { ok(false, 'old atlas registered: ' + o.atlas); continue; }
    req(fileOf(o.atlas), c.key + '|old', cell(o.atlas, o.pos));
    req(fileOf(c.atlas), c.key + '|new', cell(c.atlas, c.pos));
  }
  const px = {};
  for (const [file, rects] of Object.entries(want)) Object.assign(px, await crops(path.join(ART, file), rects));
  // 3.9.1 redrew these on purpose: Flower's card (the Seed / Flower rework art), the renamed boss's chip (a new boss).
  const REDRAWN = new Set(['m_poke_flower', 'bl_poke_iridescent_hacker']);
  const same = [], touched = [], differ = [], outside = [];
  for (const c of cards) {
    const a = px[c.key + '|old'], b = px[c.key + '|new'];
    if (!a || !b) continue;
    if (!a.inside || !b.inside) { outside.push(c.key); continue; }
    const d = meanDiff(a.px, b.px);
    if (d === 0) same.push(c.key); else if (d <= 3) touched.push(`${c.key} ${d.toFixed(2)}`); else differ.push(`${c.key} ${d.toFixed(1)}`);
  }
  const unexpected = differ.filter((s) => !REDRAWN.has(s.split(' ')[0]));
  console.log(`art: ${cards.length} Pokermon cards on 3.9.1 sheets — ${same.length} identical, ${touched.length} touched up, redrawn: ${differ.join(', ') || 'none'}`);
  ok(cards.length > 500, `Pokermon cards on 3.9.1 sheets checked (${cards.length})`);
  ok(outside.length === 0, 'every 3.9.1 cell lies inside its sheet', outside);
  ok(unexpected.length === 0, `every card shows the same picture at its 3.9.1 cell (${same.length} identical, ${touched.length} touched up)`, unexpected);
  ok(differ.length === REDRAWN.size, 'the redrawn ones are the listed ones', differ);
  // The moved jokers (3.9.1 re-laid the Natdex legendaries / forms into the Gen sheets): their new cells, by name.
  for (const n of ['aegislash', 'arceus', 'vivillon', 'flabebe', 'pumpkaboo', 'gourgeist', 'zygarde']) {
    const c = C(n);
    if (!c) continue;
    ok(same.includes(c.key) || touched.some((s) => s.startsWith(c.key + ' ')), `moved by 3.9.1: ${n} (${c.atlas} ${c.pos.x},${c.pos.y}) shows its 3.2.1 picture`);
  }
  // Held on the 3.2.1 sheet: Unown (3.9.1's card is the reworked one); the add-ons keep the 3.2.1 sheets.
  ok(C('unown').atlas === 'poke_AtlasJokersBasicGen02', 'Unown keeps its 3.2.1 card', C('unown').atlas);
  ok(C('rotomdex').atlas === 'poke_AtlasJokersBasicOthers391' && P_CENTERS.b_poke_stadiumdeck.atlas === 'poke_AtlasDecksBasic391' && P_CENTERS.c_poke_fake_banker.atlas === 'poke_AtlasJokersSeriesAGen03', 'the batch-1 placeholder art is kept (Rotom Dex, decks, Jirachi wishes)');
}

done();
